      { id: 2, question: 'When is useReducer preferred over useState?', options: ['For boolean toggles', 'When state depends on previous values or has complex logic', 'For every piece of state', 'When you need local storage sync'], correctIndex: 1, explanation: 'useReducer is preferred when state transitions are complex, involve multiple sub-values, or depend on the previous state.' },
      { id: 3, question: 'Should you mutate the existing state object in a reducer?', options: ['Yes, it is more efficient', 'No, always return a new state object', 'Only for primitive values', 'Only when using Immer'], correctIndex: 1, explanation: 'Reducers must be pure functions that never mutate the existing state. Always return new state objects to ensure React detects changes.' }
