      { id: 2, question: 'Can you derive multiple IDs from a single useId call?', options: ['No, useId returns only one ID', 'Yes, by appending suffixes to the base ID', 'Only with a custom hook', 'Only in class components'], correctIndex: 1, explanation: 'You can call useId once and derive multiple related IDs by appending suffixes like -input or -error to the base ID.' },
      { id: 3, question: 'What happens if you use Math.random() for element IDs in SSR?', options: ['It works perfectly', 'Server and client generate different IDs causing hydration mismatch', 'React ignores random IDs', 'The page crashes'], correctIndex: 1, explanation: 'Math.random generates different values on server and client causing hydration mismatches. useId generates consistent IDs for both.' }
